PRE_="/* ▼▼▼ ARCH·90a · НАЧАЛО ВЫРЕЗАЕМОГО БЛОКА ▼▼▼ (1.5.31 α · FPS: 30 / 60 / без ограничения)\n   A-27 · предел частоты обработанных кадров. Решает только, обрабатывать ли очередной вызов rAF; игровой шаг остаётся 1/60 (STEP74),\n   накопитель ACC74 и MAXN74 не меняются, глобальный requestAnimationFrame не подменяется. Срок следующего кадра накапливается\n   (FC27.next += T), поэтому средняя частота точная на любом экране (30.00 / 60.00 на 60–240 Гц), а не «каждый N-й кадр».\n   Допуск — половина периода экрана (оценка по интервалам rAF), но не больше половины периода предела. Провал больше 2T (фон, зависание)\n   или скачок времени назад сбрасывает срок — без всплеска кадров после возврата. Настройки: SET.fpsCap (телефон/планшет, isMob()) и\n   SET.fpsCapD (ПК) — независимы, значения 30 / 60 / 0 (без ограничения). Старый ключ fps синхронизируется при выборе на телефоне\n   (30 → 30, иначе 60): при откате на прежнюю версию телефон ведёт себя как выбрано. Сохранённые до 1.5.31 настройки: fps 30 → fpsCap 30,\n   fps 60 → 0 (прежний «60» не ограничивал частоту). Выключение: window.__archOff=['A-27'] до загрузки — прежнее условие пропуска и\n   прежние две кнопки. Старый frame() (A-20 выкл.) не тронут. Откат — снятие патча 90a.\n   Фаза: первый кадр под пределом отсчитывается от последнего обработанного (last + T), как у прежнего условия, — при 60 Гц обработанные\n   кадры «30» те же, что в 1.5.24. Если на телефоне старый ключ fps расходится с fpsCap по «30» (его записала прежняя версия при откате\n   или облако с неё), действует старый ключ: fps 30 → предел 30, иначе без ограничения — это последний выбор игрока. */\nARCH.fc27=!ARCH.off['A-27'];const FC27={last:0,next:0,disp:0};\nfunction fpsCur27(){if(!isMob())return SET.fpsCapD;const c=SET.fpsCap,o=SET.fps===30;return o!==(c===30)?(o?30:0):c;}\nfunction fpsCap27(){if(!ARCH.fc27)return 0;const c=fpsCur27();return c===30||c===60?c:0;}\nfunction gate27(now){const cap=fpsCap27();\n  if(FC27.last){const d=now-FC27.last;if(d>0&&d<100)FC27.disp=FC27.disp?FC27.disp+(d-FC27.disp)*.1:d;}FC27.last=now;\n  if(cap<=0){FC27.next=0;return true;}\n  const T=1000/cap,tol=Math.min(T*.5,Math.max(1,FC27.disp*.5));\n  if(!FC27.next&&now>=last&&now-last<2*T)FC27.next=last+T;\n  if(!FC27.next||now<FC27.next-4*T||now-FC27.next>2*T){FC27.next=now+T;return true;}\n  if(now<FC27.next-tol)return false;\n  FC27.next+=T;return true;}\nfunction fpsPick27(raw){const v=[30,60,0].find(o=>String(o)===raw);if(v===undefined)return;const mob=isMob();SET[mob?'fpsCap':'fpsCapD']=v;if(mob)SET.fps=v===30?30:60;\n  saveSet();applySettings();renderSetScreen();buzz('tap');}\n"+END6%'90a'
S_=[(',shake:1,noErase:false,lessFx:false};', ',shake:1,noErase:false,lessFx:false,fpsCap:0,fpsCapD:0};/* ARCH·90a: fpsCap — телефон/планшет, fpsCapD — ПК; 0 — без ограничения */'), ("quality:['auto',0,1,2],fps:[60,30],textScale:", "quality:['auto',0,1,2],fps:[60,30],fpsCap:[30,60,0],fpsCapD:[30,60,0],textScale:"), ("return v&&typeof v==='object'&&!Array.isArray(v)?v:{};})());\n", "return v&&typeof v==='object'&&!Array.isArray(v)?v:{};})());\n{const v=store('void_settings');if(!(v&&typeof v==='object'&&!Array.isArray(v)&&'fpsCap' in v))SET.fpsCap=SET.fps===30?30:0;}/* ARCH·90a: прежний «30» — предел на телефоне, прежний «60» — предела не было */\n"), ("fps:[['КАДРЫ',[[60,'60'],[30,'30']]]]", "fps:[['КАДРЫ',ARCH.fc27?[[30,'30'],[60,'60'],[0,'БЕЗ ОГРАНИЧЕНИЯ']]:[[60,'60'],[30,'30']]]]"), ('String(SET[k])===String(v)', "String(k==='fps'&&ARCH.fc27?fpsCur27():SET[k])===String(v)"), ('opts=SET_OPT[k];if(!opts)return;', "opts=SET_OPT[k];if(!opts)return;if(k==='fps'&&ARCH.fc27){fpsPick27(raw);return;}/* ARCH·90a */"), ("fps:'30 кадров — дольше держит батарея, 60 — плавнее.'", "fps:ARCH.fc27?'30 — дольше держит батарея. 60 — ровно 60 кадров. Без ограничения — сколько успевает экран (прежний режим «60»). Скорость игры одинаковая.':'30 кадров — дольше держит батарея, 60 — плавнее.'"), ('function frame74(now){\n  if(isMob()&&SET.fps===30&&now-last<29&&now>=last){requestAnimationFrame(frame);return;}', 'function frame74(now){\n  if(ARCH.fc27){if(!gate27(now)){requestAnimationFrame(frame);return;}}else if(isMob()&&SET.fps===30&&now-last<29&&now>=last){requestAnimationFrame(frame);return;}/* ARCH·90a A-27 */')]
